shell_commands:
/usr/bin/zsh -lc "node --input-type=module <<'EOF'
import {readFileSync} from 'node:fs';
const spec = readFileSync('specs/hal-engine-websocket-protocol/spec.md', 'utf8');
const test = readFileSync('src/transport/ws/messageHandler.test.ts', 'utf8').split('\\n');
const re = /\\[validated by: (["'^'"\\]]+)\\]\\(\\.\\.\\/\\.\\.\\/src\\/transport\\/ws\\/messageHandler\\.test\\.ts#L(\\d+)\\)/g;
for (const match of spec.matchAll(re)) {
  const title = match[1];
  const line = test.findIndex(row => row.includes("'`it('"'"'${title}'"'"'`) || row.includes(`it('"\\\""'${title}'"\\\""'`)) + 1;
  console.log(`${match[2]} -> ${line}: ${title}`);
}
EOF'
